<?php $reading=\Chengyu\Services\Editorial::reading($a->content,$s,$item,$me);
if($s->get('article_author_card') && $s->get('show_authors')):
$author=$a->db->one("SELECT id,username,display_name,avatar_id,bio,verified FROM cy_users WHERE id=? AND status='active'",[(int)$item['author_id']]);if($author): ?>
<section class="panel article-author-card"><?= avatar($author,'small') ?><div><a href="<?= e(url('user',['id'=>$author['id']])) ?>"><strong><?= e($author['display_name']) ?></strong></a><?php if($author['bio']): ?><p><?= e(\Chengyu\Core\Input::clip($author['bio'],200)) ?></p><?php endif ?></div><a class="text-link" href="<?= e(url('user',['id'=>$author['id']])) ?>"><?= t('Author profile') ?><?= icon('arrow') ?></a></section>
<?php endif;endif ?>
<?php if($reading['previous'] || $reading['next']): ?><nav class="article-neighbors" aria-label="<?= t('Adjacent articles') ?>"><?php foreach(['previous'=>'Previous article','next'=>'Next article'] as $key=>$label):$neighbor=$reading[$key]; ?><div><?php if($neighbor): ?><a class="panel" href="<?= e(item_url($neighbor)) ?>"><small><?= t($label) ?></small><strong><?= e($neighbor['title']) ?></strong></a><?php endif ?></div><?php endforeach ?></nav><?php endif ?>
<?php if($reading['related']): ?><section class="panel related-reading"><h2><?= t('Related reading') ?></h2><div><?php foreach($reading['related'] as $related): ?><a href="<?= e(item_url($related)) ?>"><strong><?= e($related['title']) ?></strong><?php if($s->get('show_dates')): ?><time><?= dt((int)$related['created_at'],'Y-m-d') ?></time><?php endif ?></a><?php endforeach ?></div></section><?php endif ?>
